import os; _R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))  # جذر المستودع (يعمل في أي نسخة عمل)
"""مراجعة المحرر: عنوان الصفحة h1، تبويب «النشر» (منشورات التصميم وإدارتها)، الإرسال بضغطتين وإظهار الخطأ،
الأيقونات (البحث فوقها وصفوف تُمرَّر)، «الوسائط» في العروض، وحذف الجمل التقنية، والحركة الهادئة — في الموقع (1440) والتطبيق (390)."""
import asyncio, sys, datetime
sys.path.insert(0, _R + '/v6')
from t6 import setup, URL, OUT, THM
from playwright.async_api import async_playwright
APP = URL.replace('index.html', 'app.html')
def ok(c, m): print(('✓ ' if c else '✗ ') + m)
async def clean(pg):
    await pg.evaluate("document.querySelectorAll('.coach').forEach(x=>x.remove())")
async def close_modals(pg):
    for _ in range(4):
        if await pg.query_selector('.modal'): await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
async def tg_setup(pg):
    await pg.evaluate("API6.me('set_save', JSON.stringify({ tgToken: '123456:ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghij' }))")
    await pg.evaluate("API6.me('prog_save', JSON.stringify({ id: 'academy', tg: { chat: '@jeel_demo', link: 'https://example.org/join' } }))")
    await pg.evaluate("refreshBundle()"); await pg.wait_for_timeout(1200)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={'width': 1440, 'height': 900})
        errs = await setup(pg)
        await tg_setup(pg)
        await pg.goto(URL + '#/e/ithmar/ann_cards'); await pg.wait_for_timeout(2800); await clean(pg)
        # ١) العنوان h1 هو اسم التصميم، ولا يتغير شكله
        h = await pg.evaluate("(function(){const hs=[...document.querySelectorAll('h1')].filter(h=>h.getBoundingClientRect().width>0); const i=document.querySelector('h1.e-h1 input.e-name'); return [hs.length, !!i && i.value===ED.doc.name, getComputedStyle(document.querySelector('h1.e-h1')).fontSize===getComputedStyle(document.querySelector('.e-top')).fontSize];})()")
        ok(h[0] == 1 and h[1], 'editor page has exactly one visible h1 = the design name: %s' % h)
        # ٢) الشريط: «النشر» آخر الأدوات، والزر العلوي يحمل اسمه
        rail = await pg.evaluate("[...document.querySelectorAll('#e_rail button')].map(b=>b.dataset.tab)")
        ok(rail[-1] == 'pub', 'publish tab is last in the rail: ' + ','.join(rail))
        ok((await pg.inner_text('#e_cap')).strip() == 'النشر', 'top bar button is labelled «النشر»')
        # ٣) المحتوى: الجملة الواصفة تحت العنوان، ولا تلميح في الأسفل
        ok(await pg.evaluate("!document.querySelector('.e-panel .tip6') && /نجمتين/.test(document.querySelector('.e-panel .phd .tiny').textContent)"), 'content: describing sentence under heading, no bottom tip')
        # ٤) العناصر: الأيقونات
        await pg.evaluate("ED.mode='full'; buildRail(); openTab('els')"); await pg.wait_for_timeout(900)
        txt = await pg.inner_text('#e_panel')
        ok('Tabler' not in txt and 'MIT' not in txt and 'رخصة' not in txt and 'خدمة خارجية' not in txt, 'no licence/technical notes in elements panel')
        ok(txt.count('أيقونات') == 1 and 'أيقونات أكثر' not in txt, 'one icons section (identity + full set merged)')
        geo = await pg.evaluate("""(function(){const q=document.querySelector('.icq'), s=document.querySelector('.icstrip'), hd=[...document.querySelectorAll('.e-panel .psh')].find(h=>h.textContent==='أيقونات'), hint=hd.nextElementSibling;
          const t=s.querySelector('.icb').getBoundingClientRect(); return {qTop:q.getBoundingClientRect().top, sTop:s.getBoundingClientRect().top, hintIsP: hint.tagName==='P' && /ابحث/.test(hint.textContent), tileH:t.height, stripH:s.getBoundingClientRect().height, scrollable:s.scrollWidth>s.clientWidth+20, rows:new Set([...s.querySelectorAll('.icb')].map(x=>Math.round(x.getBoundingClientRect().top))).size};})()""")
        ok(geo['hintIsP'] and geo['qTop'] < geo['sTop'], 'icon hint directly under heading and search ABOVE the icons')
        ok(geo['tileH'] <= 64 and geo['rows'] == 3 and geo['stripH'] < 220, 'icons smaller, exactly 3 rows: %s' % geo)
        ok(geo['scrollable'] and await pg.evaluate("document.querySelector('.hpager').classList.contains('more-l')"), 'icons page horizontally with a visible «more» cue')
        await pg.evaluate("document.querySelector('.icstrip').scrollIntoView({block:'center'})"); await pg.wait_for_timeout(300)
        await pg.screenshot(path=OUT + 'p1_icons.png')
        x0 = await pg.evaluate("document.querySelector('.icstrip').scrollLeft")
        await pg.click('.hpnx'); await pg.wait_for_timeout(700)
        x1 = await pg.evaluate("document.querySelector('.icstrip').scrollLeft")
        ok(abs(x1 - x0) > 100 and await pg.evaluate("document.querySelector('.hpager').classList.contains('more-r')"), 'pager arrow moves to the next page (%d→%d) and shows a back arrow' % (x0, x1))
        await pg.fill('.icq', 'كتاب'); await pg.wait_for_timeout(300)
        n = await pg.evaluate("document.querySelectorAll('.icstrip .icb').length")
        ok(0 < n < 6 and 'نتيجة' in await pg.inner_text('.iccount'), 'icon search filters (%d)' % n)
        L0 = await pg.evaluate("S.layers.length"); await pg.click('.icstrip .icb'); await pg.wait_for_timeout(500)
        ok(await pg.evaluate("S.layers.length") == L0 + 1, 'clicking an icon adds it to the design')
        # ٥) الحركة: إعادة بناء اللوحة نفسها لا تعيد حركة الظهور
        await pg.evaluate("buildPanel()"); ok(not await pg.evaluate("document.querySelector('#e_panel .pbody').classList.contains('fresh')"), 'rebuilding the same panel does not replay the entrance motion')
        # ٦) التحديد: لون الواجهة لا الأسود
        selbg = await pg.evaluate("getComputedStyle(document.querySelector('.phd h3'),'::selection').backgroundColor")
        ok(selbg not in ('rgb(0, 0, 0)', 'rgba(0, 0, 0, 0)'), 'text selection uses a soft accent tint: ' + selbg)
        # ٧) النشر: الزر العلوي يفتح التبويب والنافذة معاً
        await pg.click('#e_cap'); await pg.wait_for_timeout(900)
        ok(await pg.evaluate("ED.tab==='pub' && !!document.querySelector('.modal .caped') && !!document.querySelector('#e_panel #pub_cap')"), '«النشر» opens the publish tab with the caption dialog on top')
        nm = await pg.evaluate("document.querySelectorAll('.modal').length")
        await pg.click('.capsend .btn.dark'); await pg.wait_for_timeout(300)
        armed = await pg.evaluate("(function(){const b=document.querySelector('.capsend .btn.dark'); return [b.classList.contains('arm'), b.textContent];})()")
        ok(armed[0] and 'مرة أخرى' in armed[1] and await pg.evaluate("document.querySelectorAll('.modal').length") == nm and await pg.evaluate("(window.DEMO_TG||[]).filter(c=>/sendPhoto/.test(c.url)).length") == 0, 'first press arms the button (no stacked confirm modal, nothing sent yet): ' + armed[1])
        await pg.screenshot(path=OUT + 'p2_armed.png')
        await pg.click('.capsend .btn.arm'); await pg.wait_for_timeout(250)
        busy = await pg.evaluate("document.querySelector('.capsend .btn.dark').classList.contains('busy') || document.querySelector('.capsend .btn.dark').classList.contains('done')")
        await pg.wait_for_timeout(3500)
        ok(busy and await pg.evaluate("(window.DEMO_TG||[]).filter(c=>/sendPhoto/.test(c.url)).length") == 1 and await pg.evaluate("document.querySelector('.capsend .btn.dark').classList.contains('done')"), 'second press sends: busy → ✓ أُرسل')
        await close_modals(pg); await pg.wait_for_timeout(1200)
        t = await pg.inner_text('#e_panel')
        ok('السابقة (1)' in t and 'أُرسل' in t, 'publish tab lists the sent post (unsaved design: this session)')
        ok('لم يُحفظ هذا التصميم بعد' in t, 'unsaved design explains that saving links future posts')
        # ٨) الجدولة من التبويب، ثم التعديل والإلغاء وإعادة الجدولة من القائمة
        await pg.click('#pub_later'); await pg.wait_for_timeout(800)
        ok(await pg.evaluate("!document.querySelector('.capwhen').hidden && /جدول/.test(document.querySelector('.capsend .btn.dark').textContent)"), '«جدوله في موعد» opens the dialog in schedule mode')
        await pg.click('.capsend .btn.dark'); await pg.wait_for_timeout(2500)
        ok(await pg.evaluate("/جُدول في/.test(document.querySelector('.capsend .btn.dark').textContent)"), 'scheduled from the publish tab')
        await close_modals(pg); await pg.wait_for_timeout(1200)
        t = await pg.inner_text('#e_panel')
        ok('القادمة (1)' in t and 'مجدول' in t, 'queued post listed under «القادمة» with its status')
        await pg.screenshot(path=OUT + 'p3_pub_list.png')
        await pg.click('.pubrow.queued .pubacts button:has-text("عدّل")'); await pg.wait_for_timeout(800)
        ok(await pg.evaluate("!!document.querySelector('.modal .pdgrid')"), '«عدّل» opens the post dialog (time, text, repeat)')
        await pg.fill('.modal .capwhen input[type=time]', '21:15'); await pg.wait_for_timeout(200)
        await pg.click('.modal .pdr .btn.dark'); await pg.wait_for_timeout(1800)
        await close_modals(pg); await pg.wait_for_timeout(1200)
        ok('٢١:١٥' in await pg.inner_text('.pubrow.queued') or '9:15' in await pg.inner_text('.pubrow.queued') or '٩:١٥' in await pg.inner_text('.pubrow.queued'), 'edited time shows in the list: ' + (await pg.inner_text('.pubrow.queued .pubtime')))
        await pg.click('.pubrow.queued .pubacts button:has-text("ألغِ")'); await pg.wait_for_timeout(500)
        await pg.click('.modal:last-of-type .acts .btn.danger'); await pg.wait_for_timeout(2200)
        ok(await pg.evaluate("document.querySelectorAll('.pubrow.queued').length") == 0 and await pg.evaluate("document.querySelectorAll('.pubrow.cancelled').length") == 1, 'cancel from the list → cancelled')
        await pg.click('.pubrow.cancelled .pubacts button:has-text("أعد جدولته")'); await pg.wait_for_timeout(600)
        await pg.click('.modal:last-of-type .acts .btn.dark'); await pg.wait_for_timeout(2500)
        await close_modals(pg); await pg.wait_for_timeout(1000)
        ok(await pg.evaluate("document.querySelectorAll('.pubrow.queued').length") == 1, 'requeue from the list → queued again')
        # ٩) الخطأ يظهر واضحاً مع «حاول مرة أخرى»
        await pg.click('#pub_cap'); await pg.wait_for_timeout(800)
        await pg.evaluate("(function(){const o=API6.me; API6.me=function(a){ if(a==='tg_send'){ API6.me=o; return Promise.reject(new Error('Bad Request: chat not found')); } return o.apply(API6, arguments); };})()")
        await pg.click('.capsend .btn.dark'); await pg.wait_for_timeout(200); await pg.click('.capsend .btn.arm'); await pg.wait_for_timeout(1500)
        ok(await pg.evaluate("!document.querySelector('.capafter').hidden && document.querySelector('.capafter').classList.contains('bad') && /chat not found/.test(document.querySelector('.capafter').textContent) && /حاول مرة أخرى/.test(document.querySelector('.capafter').textContent)"), 'send error shown inline with retry')
        ok(await pg.evaluate("!document.querySelector('.capsend .btn.dark').classList.contains('arm') && /أرسل الآن/.test(document.querySelector('.capsend .btn.dark').textContent)"), 'button returns to «أرسل الآن» after an error')
        await pg.screenshot(path=OUT + 'p4_error.png')
        await pg.click('.capafter .btn'); await pg.wait_for_timeout(3500)
        ok(await pg.evaluate("document.querySelector('.capsend .btn.dark').classList.contains('done')"), 'retry sends')
        await close_modals(pg)
        # ١٠) بعد الحفظ: المنشورات مربوطة بالتصميم
        await pg.evaluate("saveRemote(true)"); await pg.wait_for_timeout(1500)
        await pg.click('#pub_cap'); await pg.wait_for_timeout(800); await pg.click('.capsend .btn.dark'); await pg.wait_for_timeout(200); await pg.click('.capsend .btn.arm'); await pg.wait_for_timeout(3500)
        q = await pg.evaluate("API6.me('tg_queue','academy').then(l=>l.filter(x=>x.item===ED.doc.id).length)")
        ok(q >= 1, 'post sent after saving carries the design id (%d)' % q)
        await close_modals(pg); await pg.wait_for_timeout(1200)
        ok('لم يُحفظ' not in await pg.inner_text('#e_panel'), 'saved design: no «save first» note')
        await pg.screenshot(path=OUT + 'p5_pub_saved.png')
        # ١١) العرض: «الوسائط» في مكان واحد
        await pg.evaluate("ED.leaveOK=true"); await pg.goto(URL + '#/'); await pg.wait_for_timeout(1000)
        await pg.evaluate("openDeckNew('ishraq',[{tpl:'sl_cover',d:{}},{tpl:'sl_points',d:{}}],'عرض')"); await pg.wait_for_timeout(2500); await clean(pg)
        await pg.evaluate("ED.mode='full'; buildRail()")
        rail = await pg.evaluate("[...document.querySelectorAll('#e_rail button')].map(b=>b.dataset.tab+':'+b.textContent)")
        ok('imgs:الوسائط' in rail and not any(r.startswith('pub:') for r in rail), 'deck rail: «الوسائط» and no publish tab')
        await pg.evaluate("openTab('els')"); await pg.wait_for_timeout(600)
        ok('فيديو من الجهاز' not in await pg.inner_text('#e_panel'), 'media no longer in elements')
        await pg.evaluate("openTab('imgs')"); await pg.wait_for_timeout(600)
        t = await pg.inner_text('#e_panel')
        ok(t.strip().startswith('الوسائط') and 'فيديو من الجهاز' in t and 'رابط يوتيوب' in t and 'صور مجانية' in t, 'media merged into «الوسائط» panel')
        await pg.screenshot(path=OUT + 'p6_deck_media.png')
        print('ERRORS', [e for e in errs if '404' not in e and 'favicon' not in e][:8])
        # ===== التطبيق =====
        ctx = await b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
        m = await ctx.new_page(); me = []
        m.on('pageerror', lambda e: me.append(str(e)))
        await m.goto(APP); await m.evaluate("localStorage.clear()"); await m.goto(APP + '#/login'); await m.wait_for_timeout(1000)
        await m.evaluate("DEMO.reset()"); await m.evaluate("DEMO.seed(%s)" % THM)
        await m.fill('#lg_id', 'admin'); await m.fill('#lg_pw', 'Admin#2026'); await m.click('.lgform button[type=submit]')
        await m.wait_for_selector('.mtab:not([hidden])', timeout=60000); await m.wait_for_timeout(2000); await m.evaluate("closeModals()")
        await tg_setup(m)
        await m.goto(APP + '#/e/ithmar/ann_cards'); await m.wait_for_timeout(3000); await clean(m)
        ok(await m.evaluate("document.querySelectorAll('h1.e-h1').length===1 && document.querySelector('h1.e-h1').getBoundingClientRect().width>150"), 'app: design name h1 keeps its full-width look')
        ok('pub' in await m.evaluate("railItems().map(r=>r[0])"), 'app: publish tab in the tools sheet')
        await m.click('.e-top .e-more'); await m.wait_for_timeout(500)
        await m.click('.mact button:has-text("النص المصاحب والنشر في القناة")'); await m.wait_for_timeout(900)
        ok(await m.evaluate("ED.tab==='pub' && MED.detent==='half' && !!document.querySelector('#pub_cap') && !document.querySelector('.msheet .caped')"), 'app: «…» → «النص المصاحب والنشر في القناة» opens the publish tab')
        await m.screenshot(path=OUT + 'p7_app_pub.png')
        await m.click('#pub_cap'); await m.wait_for_timeout(1000)
        await m.evaluate("document.querySelector('.capsend .btn.dark').scrollIntoView({block:'center'})")
        await m.click('.capsend .btn.dark'); await m.wait_for_timeout(300)
        ok(await m.evaluate("document.querySelectorAll('.msheet-wrap').length") == 1 and await m.evaluate("document.querySelector('.capsend .btn.dark').classList.contains('arm')"), 'app: first tap arms the button, no second sheet')
        await m.screenshot(path=OUT + 'p8_app_armed.png')
        await m.click('.capsend .btn.arm'); await m.wait_for_timeout(3500)
        ok(await m.evaluate("document.querySelector('.capsend .btn.dark').classList.contains('done')"), 'app: second tap sends (✓)')
        await m.evaluate("closeModals()"); await m.wait_for_timeout(1200)
        ok(await m.evaluate("document.querySelectorAll('.pubrow').length") == 1, 'app: sent post listed in the publish tab')
        await m.evaluate("openTab('els')"); await m.wait_for_timeout(700); await m.evaluate("sheetTo('full')"); await m.wait_for_timeout(600)
        await m.evaluate("document.querySelector('.icstrip').scrollIntoView({block:'center'})"); await m.wait_for_timeout(300)
        g = await m.evaluate("(function(){const s=document.querySelector('.icstrip'); return [new Set([...s.querySelectorAll('.icb')].map(x=>Math.round(x.getBoundingClientRect().top))).size, s.scrollWidth>s.clientWidth, document.querySelector('.icq').getBoundingClientRect().top < s.getBoundingClientRect().top];})()")
        ok(g == [3, True, True], 'app: icons in 3 scrollable rows with search above: %s' % g)
        await m.screenshot(path=OUT + 'p9_app_icons.png')
        print('M ERRORS', me[:5])
        await b.close()
asyncio.run(main())
